@MainActor func transient_BoardRestrictRectangle_selectionDisplay (
       _ prefs_selectionHiliteColor : NSColor,                     
       _ self_mX : CanariLength,                                   
       _ self_mY : CanariLength,                                   
       _ self_mWidth : CanariLength,                               
       _ self_mHeight : CanariLength,                              
       _ prefs_hiliteWidthMultipliedByTen : Int
) -> EBShape {
//--- START OF USER ZONE 2
        let x = self_mX
        let y = self_mY
        let width = self_mWidth
        let height = self_mHeight
        let r = CanariRect (left: x, bottom: y, width: width, height: height)
        var bp = BezierPath (rect: r)
        bp.lineWidth = CanariLength.pt (prefs_hiliteWidthMultipliedByTen) / 10.0
        bp.lineCapStyle = .round
        bp.lineJoinStyle = .round
        var shape = EBShape ()
        shape.add (stroke: [bp], prefs_selectionHiliteColor)
      //--- Knobs
        shape.add (knobAt: CanariPoint (x: x + width / 2.0, y: y), knobIndex: BOARD_RESTRICT_RECT_BOTTOM, .diamond, .pt (2.0))
        shape.add (knobAt: CanariPoint (x: x + width / 2.0, y: y + height), knobIndex: BOARD_RESTRICT_RECT_TOP, .diamond, .pt (2.0))
        shape.add (knobAt: CanariPoint (x: x + width, y: y + height / 2.0), knobIndex: BOARD_RESTRICT_RECT_RIGHT, .diamond, .pt (2.0))
        shape.add (knobAt: CanariPoint (x: x, y: y + height / 2.0), knobIndex: BOARD_RESTRICT_RECT_LEFT, .diamond, .pt (2.0))
      //---
        return shape
//--- END OF USER ZONE 2
}

